questionvariables.text:
kgrp(n) := block([s, out, k], s: string(n), k: slength(s), if k < 5 then s else (out: "", while k > 3 do (out: sconcat("\\,", substring(s, k-2, k+1), out), k: k-3), sconcat(substring(s, 1, k+1), out)));
ksh(v) := block([c, w, f], c: floor(100*v+1/2), w: floor(c/100), f: c-100*w, if f = 0 then kgrp(w) else sconcat(kgrp(w), ".", if f < 10 then "0" else "", string(f)));
dd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else if integerp(1000*v) then dispdp(float(v),3) else dispdp(float(v),4);
fr(v) := if integerp(v) then string(v) else sconcat("\\frac{", string(num(v)), "}{", string(denom(v)), "}");
r1(v) := floor(10*v+1/2)/10;
ix: 1+rand(10);
nv(v) := if integerp(v) then kgrp(v) else if integerp(1000*v) then string(float(v)) else sconcat("\\approx ", string(float(floor(100*v+1/2)/100)));
jn(L) := block([s], s: "", for v in L do s: if s = "" then nv(v) else sconcat(s, ",\\; ", nv(v)), s);
/* Design: classify tables as direct, inverse or neither; two named traps. Source: adapted from SMP GCSE Higher 2, Chapter 7, question F3. Each entry: three tables [kind, x label, y label, xs, ys] (kind 1 direct, 2 inverse, 3 rises from a fixed starting amount, 4 falls linearly) and the option display order. Curated list, one seed per entry. */
L: [[[[1,"Iron sheets bought","Cost (Ksh)",[2,3,5,8],[1840,2760,4600,7360]],[2,"Number of workers","Days to weed the shamba",[2,4,6,8],[60,30,20,15]],[3,"Days the tent is hired","Charge (Ksh)",[1,2,3,5],[3500,5000,6500,9500]]],[1,2,3]],[[[4,"Days since the tank was filled","Water left (litres)",[1,2,4,6],[4650,4300,3600,2900]],[1,"Bags of fertiliser","Mass (kg)",[3,4,7,10],[150,200,350,500]],[2,"Number of buses","Trips each bus makes",[2,3,4,6],[42,28,21,14]]],[2,3,1]],[[[2,"Number of pumps","Hours to empty the flooded quarry",[2,3,4,6],[48,32,24,16]],[3,"Water used in a month (cubic metres)","Water bill (Ksh)",[5,10,15,20],[850,1400,1950,2500]],[1,"Hours the posho mill runs","Maize ground (kg)",[1,2,4,5],[160,320,640,800]]],[3,1,2]],[[[1,"Hours the posho mill runs","Maize ground (kg)",[2,3,5,6],[280,420,700,840]],[4,"Weeks since harvest","Bags of maize left in the store",[2,4,6,8],[62,52,42,32]],[2,"Number of workers","Days to weed the shamba",[3,4,6,9],[36,27,18,12]]],[1,3,2]],[[[3,"Weeks after planting","Height of the seedling (cm)",[1,2,4,6],[15,18,24,30]],[2,"Number of buses","Trips each bus makes",[2,4,7,8],[28,14,8,7]],[4,"Hours driven","Distance still to go (km)",[1,2,3,5],[420,360,300,180]]],[2,1,3]],[[[2,"Number of workers","Days to weed the shamba",[2,3,5,6],[45,30,18,15]],[1,"Iron sheets bought","Cost (Ksh)",[4,5,6,9],[3400,4250,5100,7650]],[4,"Days since the tank was filled","Water left (litres)",[2,3,5,8],[5100,4650,3750,2400]]],[3,2,1]],[[[1,"Bags of fertiliser","Mass (kg)",[2,5,6,9],[100,250,300,450]],[3,"Days the tent is hired","Charge (Ksh)",[2,3,4,6],[3900,5100,6300,8700]],[1,"Hours the posho mill runs","Maize ground (kg)",[1,3,4,6],[175,525,700,1050]]],[2,3,1]],[[[4,"Weeks since harvest","Bags of maize left in the store",[1,3,5,7],[56,48,40,32]],[2,"Number of pumps","Hours to empty the flooded quarry",[2,4,6,8],[72,36,24,18]],[2,"Number of buses","Trips each bus makes",[3,4,6,12],[28,21,14,7]]],[3,1,2]],[[[2,"Number of workers","Days to weed the shamba",[4,5,8,10],[20,16,10,8]],[4,"Hours driven","Distance still to go (km)",[1,3,4,6],[365,255,200,90]],[3,"Water used in a month (cubic metres)","Water bill (Ksh)",[6,8,12,15],[970,1210,1690,2050]]],[1,2,3]],[[[3,"Weeks after planting","Height of the seedling (cm)",[2,3,5,8],[23,27,35,47]],[1,"Iron sheets bought","Cost (Ksh)",[3,6,7,10],[2340,4680,5460,7800]],[2,"Number of pumps","Hours to empty the flooded quarry",[3,4,6,8],[40,30,20,15]]],[2,1,3]]];
E: L[ix];
TB: E[1];
pm: E[2];
kd: makelist(TB[j][1], j, 1, 3);
ky: makelist(if kd[j]<=2 then kd[j] else 3, j, 1, 3);
w1: makelist(mod(ky[j],3)+1, j, 1, 3);
w2: makelist(mod(ky[j]+1,3)+1, j, 1, 3);
rt: makelist(makelist(TB[j][5][i]/TB[j][4][i], i, 1, 4), j, 1, 3);
pr: makelist(makelist(TB[j][5][i]*TB[j][4][i], i, 1, 4), j, 1, 3);
onm: ["directly proportional", "inversely proportional", "neither"];
o1: makelist([pm[i], is(pm[i]=ky[1]), onm[pm[i]]], i, 1, 3);
o2: makelist([pm[i], is(pm[i]=ky[2]), onm[pm[i]]], i, 1, 3);
o3: makelist([pm[i], is(pm[i]=ky[3]), onm[pm[i]]], i, 1, 3);
